import Foundation

/// Represents the actionable trade levels generated by OpsOdds.
public struct OpsOddsLevels: Codable, Equatable, Sendable {
    public let entryZone: [Double]?
    public let invalidation: Double?
    public let target1: Double?
    public let target2: Double?
    public let doNotChase: Bool?

    public init(
        entryZone: [Double]? = nil,
        invalidation: Double? = nil,
        target1: Double? = nil,
        target2: Double? = nil,
        doNotChase: Bool? = nil
    ) {
        self.entryZone = entryZone
        self.invalidation = invalidation
        self.target1 = target1
        self.target2 = target2
        self.doNotChase = doNotChase
    }

    public var entryZoneText: String? {
        guard let entryZone, entryZone.count >= 2 else { return nil }
        return String(format: "$%.2f – $%.2f", entryZone[0], entryZone[1])
    }

    public var invalidationText: String? {
        guard let invalidation else { return nil }
        return String(format: "$%.2f", invalidation)
    }

    public var target1Text: String? {
        guard let target1 else { return nil }
        return String(format: "$%.2f", target1)
    }

    public var target2Text: String? {
        guard let target2 else { return nil }
        return String(format: "$%.2f", target2)
    }
}

/// Represents an individual market or technical signal (supportive or opposing).
public struct OpsOddsSignal: Codable, Equatable, Identifiable, Sendable {
    public var id: String { "\(label):\(stance)" }
    public let label: String
    public let stance: String // "supportive" or "opposing"
    public let text: String

    public init(label: String, stance: String, text: String) {
        self.label = label
        self.stance = stance
        self.text = text
    }

    public var isSupportive: Bool {
        stance.lowercased() == "supportive"
    }
}

/// The complete score and real-time market data payload for a ticker.
public struct OpsOddsScore: Codable, Equatable, Identifiable, Sendable {
    public var id: String { ticker }
    public let ticker: String
    public var companyName: String?
    public var opsOdds: Int? // 1 ... 10 score
    public var band: String? // "favorable", "caution", "avoid"
    public var decision: String? // "Enter swing", "Add to swing", "Do Not Trade", "Hold", "Take profit"
    public var currentPrice: Double?
    public var previousClose: Double?
    public var priceChange: Double?
    public var priceChangePercent: Double?
    public var levels: OpsOddsLevels?
    public var instruction: String?
    public var signals: [OpsOddsSignal]?
    public var asOf: Date?
    public var isFresh: Bool
    public var quoteSource: String // "Schwab REST", "OpsOdds Real-Time", "Market Data"

    public init(
        ticker: String,
        companyName: String? = nil,
        opsOdds: Int? = nil,
        band: String? = nil,
        decision: String? = nil,
        currentPrice: Double? = nil,
        previousClose: Double? = nil,
        priceChange: Double? = nil,
        priceChangePercent: Double? = nil,
        levels: OpsOddsLevels? = nil,
        instruction: String? = nil,
        signals: [OpsOddsSignal]? = nil,
        asOf: Date? = nil,
        isFresh: Bool = true,
        quoteSource: String = "Schwab Real-Time"
    ) {
        self.ticker = ticker
        self.companyName = companyName
        self.opsOdds = opsOdds
        self.band = band
        self.decision = decision
        self.currentPrice = currentPrice
        self.previousClose = previousClose
        self.priceChange = priceChange
        self.priceChangePercent = priceChangePercent
        self.levels = levels
        self.instruction = instruction
        self.signals = signals
        self.asOf = asOf ?? Date()
        self.isFresh = isFresh
        self.quoteSource = quoteSource
    }

    public var formattedPrice: String {
        guard let currentPrice else { return "—" }
        if currentPrice >= 1000 {
            return String(format: "$%.1f", currentPrice)
        } else {
            return String(format: "$%.2f", currentPrice)
        }
    }

    public var formattedChange: String {
        guard let priceChange, let priceChangePercent else { return "" }
        let sign = priceChange >= 0 ? "+" : ""
        return String(format: "%@$%.2f (%@%.2f%%)", sign, priceChange, sign, priceChangePercent)
    }

    public var isPositiveChange: Bool {
        (priceChange ?? 0) >= 0
    }

    public var scoreText: String {
        guard let opsOdds else { return "—" }
        return "\(opsOdds)/10"
    }

    public var bandBadge: String {
        if let opsOdds {
            if opsOdds >= 8 { return "FAVORABLE" }
            if opsOdds >= 6 { return "MODERATE" }
            if opsOdds >= 4 { return "CAUTION" }
            return "UNFAVORABLE"
        }
        return (band ?? "SCORE").uppercased()
    }
}

/// Pairing state for pairing NotchTrader with OpsOdds.
public struct OpsOddsPairingState: Codable, Equatable, Sendable {
    public var deviceId: String?
    public var deviceName: String?
    public var pairingId: String?
    public var pairingCode: String?
    public var pairingChallenge: String?
    public var approvalUrl: String?
    public var pairingExpiresAt: Date?
    public var isPaired: Bool { deviceId != nil && !(deviceId?.isEmpty ?? true) }

    public init(
        deviceId: String? = nil,
        deviceName: String? = nil,
        pairingId: String? = nil,
        pairingCode: String? = nil,
        pairingChallenge: String? = nil,
        approvalUrl: String? = nil,
        pairingExpiresAt: Date? = nil
    ) {
        self.deviceId = deviceId
        self.deviceName = deviceName
        self.pairingId = pairingId
        self.pairingCode = pairingCode
        self.pairingChallenge = pairingChallenge
        self.approvalUrl = approvalUrl
        self.pairingExpiresAt = pairingExpiresAt
    }
}
